# -*- coding: utf-8 -*-
"""Supuestos del modelo. Cada valor lleva su fuente o se marca como supuesto a validar.
Valores por escenario: [Conservador, Base, Favorable]. Los precios de membresía van en ARS con IVA (como se publican)."""


def supuestos(p):
    """p = dict de parámetros calculados del censo y las fuentes (precios de mercado, costos, alquiler de la casa)."""
    I = []
    def sec(t):
        I.append({"seccion": t})
    def it(key, label, unit, vals, fuente, tipo="supuesto", fmt="n"):
        I.append({"key": key, "label": label, "unit": unit, "vals": vals, "fuente": fuente, "tipo": tipo, "fmt": fmt})

    sec("GENERALES")
    it("tc", "Tipo de cambio para pasar pesos a dólares", "ARS por USD", p["tc"], p["tc_fuente"], "dato", "ARS")
    it("iva", "Alícuota de IVA", "%", 0.21, "Ley de IVA, alícuota general.", "dato", "%")
    it("ri", "¿Responsable inscripto? (1 = sí, 0 = monotributo)", "1/0", 1, p["ri_fuente"], "supuesto")
    it("dias_habiles", "Días hábiles por mes", "días", 21, "Promedio de lunes a viernes sin feriados nacionales (aprox.).", "supuesto")
    it("meses_obra", "Meses de obra y habilitación antes de abrir", "meses", [6, 4, 3], "Supuesto a validar con el arquitecto y el gestor.", "a validar")
    sec("CAPACIDAD (casa de 450 m²: subsuelo, planta baja + patio, planta alta; distribución sin plano)")
    it("puestos_flex", "Puestos flexibles (simultáneos)", "puestos", p["puestos_flex"], p["cap_fuente"], "a validar")
    it("puestos_fijos", "Puestos fijos (escritorio asignado)", "puestos", p["puestos_fijos"], p["cap_fuente"], "a validar")
    it("oficinas_priv", "Oficinas privadas chicas (complemento)", "oficinas", p["oficinas_priv"], p["cap_fuente"], "a validar")
    it("puestos_por_oficina", "Puestos por oficina privada", "puestos", 3, "Oficina de 3 personas (aprox. 12–15 m²).", "supuesto")
    sec("USO DE LOS PUESTOS")
    it("uso_flex", "Uso real de los días incluidos (flex)", "%", [0.85, 0.80, 0.75], "Mayor uso = menos membresías por puesto (por eso el conservador usa el más alto). Supuesto a medir en la preventa.", "a validar", "%")
    it("factor_pico", "Pico de asistencia sobre el promedio (mar-jue)", "veces", [1.35, 1.30, 1.25], "Los coworkings se llenan martes a jueves; supuesto a medir.", "a validar")
    it("uso_fijo", "Uso de los puestos fijos y oficinas (para consumo)", "%", 0.8, "Supuesto.", "supuesto", "%")
    sec("PLANES Y PRECIOS (ARS por mes, con IVA, como se publican)")
    for k, (lab, d) in enumerate([("Plan 4 días por mes", 4), ("Plan 8 días por mes (≈2 por semana)", 8),
                                  ("Plan 12 días por mes (≈3 por semana)", 12), ("Plan ilimitado flex (lunes a viernes)", 21)], 1):
        it(f"dias_p{k}", f"{lab}: días incluidos", "días/mes", d, "Diseño de la oferta propuesta.", "supuesto")
    for k in range(1, 5):
        it(f"precio_p{k}", f"Precio plan {k}", "ARS/mes", p[f"precio_p{k}"], p[f"precio_p{k}_fuente"], "mercado", "ARS")
    for k in range(1, 5):
        it(f"mix_p{k}", f"Peso del plan {k} en los miembros flex", "%", p[f"mix_p{k}"], p["mix_fuente"], "a validar", "%")
    it("precio_fijo", "Puesto fijo", "ARS/mes", p["precio_fijo"], p["precio_fijo_fuente"], "mercado", "ARS")
    it("precio_oficina", "Oficina privada (3 personas)", "ARS/mes", p["precio_oficina"], p["precio_oficina_fuente"], "mercado", "ARS")
    it("precio_pase", "Pase diario", "ARS/día", p["precio_pase"], p["precio_pase_fuente"], "mercado", "ARS")
    it("precio_sala_h", "Sala de reunión por hora (externos)", "ARS/hora", p["precio_sala_h"], p["precio_sala_fuente"], "mercado", "ARS")
    it("precio_mult", "Ajuste de precios del escenario", "veces", [0.90, 1.00, 1.05], "Conservador: −10 % para competir; favorable: +5 %.", "supuesto")
    it("descuento", "Descuento promedio efectivo (promos, pago anticipado)", "%", [0.10, 0.07, 0.05], "Supuesto.", "supuesto", "%")
    it("pases_mes", "Pases diarios vendidos por mes (en régimen)", "pases", [20, 35, 50], "Supuesto a validar.", "a validar")
    it("horas_sala_mes", "Horas de sala vendidas a externos por mes (en régimen)", "horas", [10, 20, 30], "Supuesto a validar.", "a validar")
    it("otros_ingresos_usd", "Otros ingresos (domicilio comercial, eventos) en régimen", "USD/mes", [0, 100, 200], "Supuesto.", "a validar", "USD")
    it("ramp_pases", "Meses hasta vender los extras en régimen", "meses", [12, 9, 6], "Supuesto.", "supuesto")
    it("ramp_of", "Meses hasta ocupar las oficinas privadas", "meses", [10, 6, 4], "Supuesto.", "a validar")
    sec("ALTAS Y BAJAS DE MIEMBROS FLEX")
    it("miembros_ini", "Miembros al abrir (preventa / lista de espera)", "miembros", [0, 5, 10], "Depende de la preventa (ver plan de validación).", "a validar")
    it("altas_f1", "Altas por mes, meses 1 a 6", "miembros/mes", p["altas_f1"], p["altas_fuente"], "a validar")
    it("altas_f2", "Altas por mes, meses 7 a 12", "miembros/mes", p["altas_f2"], p["altas_fuente"], "a validar")
    it("altas_f3", "Altas por mes, meses 13 a 36", "miembros/mes", p["altas_f3"], p["altas_fuente"], "a validar")
    it("churn", "Bajas mensuales de miembros flex", "%", [0.08, 0.06, 0.05], p["churn_fuente"], "a validar", "%")
    it("altas_fijo", "Altas de puestos fijos por mes", "puestos/mes", [0.5, 1.0, 1.5], "Supuesto.", "a validar")
    it("churn_fijo", "Bajas mensuales de puestos fijos", "%", [0.05, 0.04, 0.03], "Supuesto (los fijos rotan menos).", "a validar", "%")
    sec("COSTOS VARIABLES")
    it("costo_puesto_dia_usd", "Café, té, agua y consumibles por puesto-día", "USD", p["costo_puesto_dia_usd"], p["costo_puesto_dia_fuente"], "estimación")
    it("comision_pct", "Comisión de cobro (tarjeta / billetera)", "% de lo cobrado", p["comision_pct"], p["comision_fuente"], "dato", "%")
    it("iibb_pct", "Ingresos Brutos CABA", "% de ventas sin IVA", p["iibb_pct"], p["iibb_fuente"], "dato", "%")
    it("idc_pct", "Impuesto a los débitos y créditos bancarios (aprox.)", "% de lo cobrado", 0.012, "Ley 25.413: 0,6 % sobre créditos + 0,6 % sobre débitos; aproximado sobre lo cobrado.", "dato", "%")
    sec("COSTOS FIJOS (USD por mes)")
    it("personal_fte", "Personal de recepción y comunidad (jornadas completas)", "personas", [1.5, 1.5, 1.5], "Lunes a viernes 8 a 20 h: una jornada completa + media.", "supuesto")
    it("costo_fte_usd", "Costo laboral por persona (sueldo + cargas)", "USD/mes", p["costo_fte_usd"], p["costo_fte_fuente"], "dato")
    it("limpieza_usd", "Limpieza", "USD/mes", p["limpieza_usd"], p["limpieza_fuente"], "estimación", "USD")
    it("internet_usd", "Internet principal + respaldo", "USD/mes", p["internet_usd"], p["internet_fuente"], "dato", "USD")
    it("servicios_usd", "Electricidad, gas y agua", "USD/mes", p["servicios_usd"], p["servicios_fuente"], "estimación", "USD")
    it("seguros_usd", "Seguros (integral y responsabilidad civil)", "USD/mes", p["seguros_usd"], p["seguros_fuente"], "estimación", "USD")
    it("software_usd", "Software de gestión y reservas", "USD/mes", p["software_usd"], p["software_fuente"], "dato", "USD")
    it("admin_usd", "Contador y administración", "USD/mes", p["admin_usd"], p["admin_fuente"], "estimación", "USD")
    it("mant_pct_anual", "Mantenimiento y reposición (anual, sobre la inversión)", "%", [0.05, 0.04, 0.04], "Supuesto.", "supuesto", "%")
    it("marketing_usd", "Publicidad digital", "USD/mes", [500, 400, 400], p["marketing_fuente"], "supuesto", "USD")
    it("comunidad_usd", "Actividades de comunidad (desayunos, charlas)", "USD/mes", [150, 150, 150], "Un desayuno de miembros y una charla por mes; supuesto.", "supuesto", "USD")
    it("otros_pct", "Otros e imprevistos (sobre los fijos)", "%", [0.08, 0.05, 0.05], "Supuesto.", "supuesto", "%")
    sec("INVERSIÓN INICIAL (USD)")
    it("m2_obra", "m² a intervenir (sin el patio)", "m²", [390, 390, 390], "450 m² totales menos el patio estimado; sin plano.", "a validar")
    it("usd_m2_obra", "Adecuación por m² (pintura, pisos, iluminación, baños, terminaciones)", "USD/m²", p["usd_m2_obra"], p["usd_m2_obra_fuente"], "estimación", "USD")
    it("m2_patio", "m² de patio a techar", "m²", [60, 60, 60], "Sin plano: supuesto a medir.", "a validar")
    it("usd_m2_patio", "Techado de patio por m²", "USD/m²", p["usd_m2_patio"], p["usd_m2_patio_fuente"], "estimación", "USD")
    it("pileta_usd", "Anulación / relleno de pileta", "USD", p["pileta_usd"], p["pileta_fuente"], "estimación", "USD")
    it("bano_acc_usd", "Baño accesible", "USD", p["bano_acc_usd"], p["bano_fuente"], "estimación", "USD")
    it("electrica_datos_usd", "Instalación eléctrica y red de datos", "USD", p["electrica_datos_usd"], p["electrica_fuente"], "estimación", "USD")
    it("clima_n", "Equipos de aire acondicionado", "equipos", [8, 8, 8], "Supuesto: un equipo cada 40–50 m² cubiertos.", "supuesto")
    it("clima_usd", "Aire acondicionado instalado (por equipo)", "USD", p["clima_usd"], p["clima_fuente"], "dato", "USD")
    it("mueble_puesto_usd", "Escritorio + silla ergonómica por puesto", "USD", p["mueble_puesto_usd"], p["mueble_fuente"], "dato", "USD")
    it("mueble_comun_usd", "Mobiliario común (salas, living, lockers)", "USD", p["mueble_comun_usd"], p["mueble_fuente"], "estimación", "USD")
    it("cabinas_n", "Cabinas para llamadas", "cabinas", [2, 3, 3], "Supuesto.", "supuesto")
    it("cabina_usd", "Cabina acústica por unidad", "USD", p["cabina_usd"], p["cabina_fuente"], "dato", "USD")
    it("cafe_equipo_usd", "Café y cocina (máquina, heladera, microondas, vajilla)", "USD", p["cafe_equipo_usd"], p["cafe_fuente"], "dato", "USD")
    it("it_seguridad_usd", "Red WiFi, UPS, control de acceso y cámaras", "USD", p["it_seguridad_usd"], p["it_fuente"], "dato", "USD")
    it("honorarios_pct", "Honorarios profesionales (sobre la obra)", "%", p["honorarios_pct"], p["honorarios_fuente"], "estimación", "%")
    it("habilitacion_usd", "Habilitación, planos de uso, incendio y trámites", "USD", p["habilitacion_usd"], p["habilitacion_fuente"], "estimación", "USD")
    it("apertura_mkt_usd", "Marketing de apertura y preventa", "USD", [2000, 2000, 2000], "Supuesto.", "supuesto", "USD")
    it("contingencia_pct", "Contingencias", "%", [0.15, 0.12, 0.10], "Práctica habitual en refacciones de casas usadas; supuesto.", "supuesto", "%")
    sec("COSTO DE OPORTUNIDAD Y FINANZAS")
    it("alquiler_casa_usd", "Alquiler de mercado de la casa que se deja de cobrar", "USD/mes", p["alquiler_casa_usd"], p["alquiler_casa_fuente"], "mercado", "USD")
    it("tasa_desc_anual", "Tasa de descuento anual en USD (la define el inversor)", "%", 0.12, "Supuesto ilustrativo: el inversor tiene que poner su propia tasa.", "a definir", "%")
    it("valor_residual_usd", "Valor residual al mes 36 (negocio y equipamiento)", "USD", 0, "Se deja en 0 para no inflar el retorno.", "supuesto", "USD")
    return I
